"""Verify Aut((Z/2)^n) = GL(n, F_2) by brute-force enumeration."""
from itertools import product
from typing import Tuple

Section = Tuple[int, ...]


def gl_order(n: int) -> int:
    r = 1
    for i in range(n):
        r *= (2 ** n - 2 ** i)
    return r


def count_automorphisms(n: int) -> int:
    space = [tuple(v) for v in product((0, 1), repeat=n)]
    zero = tuple(0 for _ in range(n))
    count = 0
    for images in product(space, repeat=n):
        seen = set()
        for x in space:
            y = zero
            for i in range(n):
                if x[i]:
                    y = tuple((a + b) % 2 for a, b in zip(y, images[i]))
            seen.add(y)
        if len(seen) == len(space):
            count += 1
    return count


for n in range(1, 4):
    print(f"n={n}: automorphisms={count_automorphisms(n)}, "
          f"|GL(n,F_2)|={gl_order(n)}")

"""Cayley representation: kinship steps as simply transitive permutations."""
from itertools import product
from typing import List, Tuple

Section = Tuple[int, ...]


def kin(n: int) -> List[Section]:
    return [tuple(v) for v in product((0, 1), repeat=n)]


def add(x: Section, y: Section) -> Section:
    return tuple((a + b) % 2 for a, b in zip(x, y))


def translation(n: int, v: Section) -> List[Section]:
    return [add(x, v) for x in kin(n)]


def simply_transitive(n: int) -> bool:
    sp = kin(n)
    return all(sum(1 for v in sp if add(x, v) == y) == 1
               for x in sp for y in sp)


for n in range(1, 5):
    distinct = {tuple(translation(n, v)) for v in kin(n)}
    print(f"n={n}: distinct kinship permutations={len(distinct)} (=2^n), "
          f"simply transitive={simply_transitive(n)}")

