def gl_order(n: int) -> int:
    """|Aut((Z/2)^n)| = |GL(n, F_2)| = prod_{i=0}^{n-1} (2^n - 2^i)."""
    result: int = 1
    for i in range(n):
        result *= (2 ** n - 2 ** i)
    return result

