function COUNT_AUTOMORPHISMS(n):
    space <- all vectors in {0,1}^n
    count <- 0
    for each tuple (images[0..n-1]) in space^n:
        seen <- empty set
        for x in space:
            y <- 0
            for i in 0..n-1:
                if x[i] = 1: y <- y XOR images[i]
            add y to seen
        if |seen| = |space|: count <- count + 1
    return count

