function MARRIAGE_COSET_CLASS(n, m):
    shift <- last_coordinate(m)
    for x in {0,1}^n:
        spouse <- x XOR m
        assert last_coordinate(spouse) = (last_coordinate(x) + shift) mod 2
    return 'endogamous' if shift = 0 else 'exogamous'
